SELECT id, symbol, interval_code, candle_open_time, generated_at, created_at, decision, original_decision, total_score, confidence_score, final_entry_allowed, atr_immediate_entry_allowed, atr_entry_type, atr_recommended_position_percent, atr_at_signal, latest_price, stop_loss, take_profit, risk_reward_ratio, data_quality_valid FROM crypto_ai.trade_signal WHERE id IN (159285, 159320, 159321, 159407, 159408) ORDER BY generated_at;